const item = $input.first();
const webhookData = $('Webhook Lead').first().json;

// Default: lead necalificat in caz de eroare OpenAI
let qualification = {
  qualified: false,
  score: 0,
  urgency: '6+ luni',
  budget_category: 'sub 50k',
  summary_ro: 'Eroare la procesarea automata. Review manual necesar.',
  reason: 'Eroare OpenAI sau raspuns invalid'
};

try {
  // Extrage continutul din raspunsul OpenAI (simplifyOutput: true)
  const content = item.json?.message?.content ||
                  item.json?.choices?.[0]?.message?.content ||
                  item.json?.text || '';

  if (content) {
    // Elimina eventualele blocuri markdown ```json ... ```
    const cleaned = content.replace(/```json\n?|\n?```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    qualification = { ...qualification, ...parsed };
  }
} catch (e) {
  qualification.reason = 'Eroare procesare AI: ' + (e.message || 'JSON invalid');
}

return [{
  json: {
    // Date originale lead
    lead_name: webhookData.lead_name || '',
    lead_email: webhookData.lead_email || '',
    lead_phone: webhookData.lead_phone || '',
    property_type: webhookData.property_type || '',
    budget_ron: webhookData.budget_ron || 0,
    message: webhookData.message || '',
    source: webhookData.source || '',
    // Rezultate calificare AI
    qualified: qualification.qualified || false,
    score: qualification.score || 0,
    urgency: qualification.urgency || '6+ luni',
    budget_category: qualification.budget_category || 'sub 50k',
    summary_ro: qualification.summary_ro || '',
    reason: qualification.reason || '',
    // Metadata
    timestamp: new Date().toISOString(),
    status: (qualification.qualified === true) ? 'CALIFICAT' : 'NECALIFICAT'
  }
}];
